using System;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    /// <summary>
    /// AOT-compatible JSON converter for <see cref="ResponseError"/>.
    /// The built-in converter on ResponseError uses an inaccessible nested type,
    /// so the STJ source generator cannot reference it.
    /// </summary>
    internal sealed class ResponseErrorAotConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var doc = JsonDocument.ParseValue(ref reader);
            var root = doc.RootElement;
            var code = root.TryGetProperty("code", out var c) ? c.GetString() : null;
            var message = root.TryGetProperty("message", out var m) ? m.GetString() : null;
            return new ResponseError(code, message);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code", value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message", value.Message);
            }
            if (value.Target != null)
            {
                writer.WriteString("target", value.Target);
            }
            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WritePropertyName("details");
                writer.WriteStartArray();
                foreach (var detail in value.Details)
                {
                    Write(writer, detail, options);
                }
                writer.WriteEndArray();
            }
            writer.WriteEndObject();
        }
    }
}

